alter table public.ai_analysis_requests add column if not exists tenant_id uuid, add column if not exists input_snapshot jsonb;

update public.ai_analysis_requests r set tenant_id=c.tenant_id from public.candidaturas c where r.tenant_id is null and c.candidato_id::text=r.candidato_id::text and c.vaga_id::text=r.vaga_id::text;

alter table public.ai_analysis_requests alter column tenant_id set not null, alter column input_snapshot set default '{}'::jsonb;

alter table public.ai_analysis_requests drop constraint if exists ai_analysis_requests_status_check;

alter table public.ai_analysis_requests add constraint ai_analysis_requests_status_check check(status in ('queued','processing','completed','failed'));

alter table public.ai_analysis_requests alter column status set default 'queued';

drop function if exists public.claim_ai_analysis_request(text,uuid,uuid,uuid,text,text,text,boolean);

create or replace function public.claim_ai_analysis_request(p_request_key text,p_tenant_id uuid,p_actor_id uuid,p_candidato_id uuid,p_vaga_id uuid,p_prompt_version text,p_model text,p_input_hash text,p_input_snapshot jsonb,p_force boolean default false) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_row public.ai_analysis_requests%rowtype; begin if trim(coalesce(p_request_key,''))='' or length(p_request_key)>500 or p_tenant_id is null or p_actor_id is null or p_candidato_id is null or p_vaga_id is null or trim(coalesce(p_prompt_version,''))='' or trim(coalesce(p_model,''))='' or p_input_hash !~ '^[0-9a-f]{64}$' or p_input_snapshot is null then raise exception using errcode='22023',message='invalid_ai_analysis_claim'; end if; perform pg_advisory_xact_lock(hashtextextended('ai-analysis:'||p_request_key,0)); select * into v_row from public.ai_analysis_requests where request_key=p_request_key for update; if not found then insert into public.ai_analysis_requests(request_key,tenant_id,actor_id,candidato_id,vaga_id,prompt_version,model,input_hash,input_snapshot,status) values(p_request_key,p_tenant_id,p_actor_id,p_candidato_id,p_vaga_id,p_prompt_version,p_model,p_input_hash,p_input_snapshot,'queued'); return jsonb_build_object('claimed',false,'status','queued'); end if; if not p_force and v_row.status='completed' and v_row.input_hash=p_input_hash and v_row.result is not null then return jsonb_build_object('claimed',false,'status','completed','result',v_row.result); end if; if v_row.status='processing' and v_row.lease_expires_at is not null and v_row.lease_expires_at>now() then return jsonb_build_object('claimed',false,'status','processing','retry_after',greatest(1,ceil(extract(epoch from(v_row.lease_expires_at-now())))::integer)); end if; update public.ai_analysis_requests set tenant_id=p_tenant_id,actor_id=p_actor_id,candidato_id=p_candidato_id,vaga_id=p_vaga_id,prompt_version=p_prompt_version,model=p_model,input_hash=p_input_hash,input_snapshot=p_input_snapshot,claim_token=null,lease_expires_at=null,status='queued',result=null,error_code=null,started_at=now(),completed_at=null,updated_at=now() where request_key=p_request_key; return jsonb_build_object('claimed',false,'status','queued'); end; $$;

create or replace function public.claim_next_ai_analysis_request() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_row public.ai_analysis_requests%rowtype; v_token uuid:=gen_random_uuid(); begin select * into v_row from public.ai_analysis_requests where status='queued' or(status='processing' and(lease_expires_at is null or lease_expires_at<=now())) order by updated_at asc for update skip locked limit 1; if not found then return null; end if; update public.ai_analysis_requests set claim_token=v_token,lease_expires_at=now()+interval '2 minutes',status='processing',started_at=now(),updated_at=now() where id=v_row.id; return jsonb_build_object('id',v_row.id,'request_key',v_row.request_key,'tenant_id',v_row.tenant_id,'actor_id',v_row.actor_id,'candidato_id',v_row.candidato_id,'vaga_id',v_row.vaga_id,'prompt_version',v_row.prompt_version,'model',v_row.model,'input_hash',v_row.input_hash,'input_snapshot',v_row.input_snapshot,'claim_token',v_token); end; $$;

create index if not exists idx_ai_analysis_requests_worker on public.ai_analysis_requests(status,updated_at);

create index if not exists idx_ai_analysis_requests_tenant_lookup on public.ai_analysis_requests(tenant_id,candidato_id,vaga_id,input_hash);